import { Fragment, useEffect, useState } from 'react';
import { IconCheck } from '../../../icons/check';
import { IconCopy } from '../../../icons/copy';
import { announce } from '../../../primitives/announce';
import { Button } from '../../actions/button/Button';
import './code-panel.css';

export interface CodePanelProps {
  /** The source text: what gets copied. */
  code: string;
  /** Pre-highlighted HTML for the same code (for example from Shiki at build time). Plain text is shown without it. */
  html?: string;
  filename?: string;
  /** Called after a successful copy, for example to show a toast. Otherwise the panel announces it. */
  onCopied?: () => void;
  onCopyFailed?: () => void;
  className?: string;
}

/**
 * Source code with line numbers and a copy button. Highlighting is optional and expected
 * to be done ahead of time, so no highlighter ships to the browser. The code area scrolls
 * and is focusable, so keyboard users can scroll it too.
 */
export function CodePanel({
  code,
  html,
  filename,
  onCopied,
  onCopyFailed,
  className,
}: CodePanelProps) {
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 2000);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      if (onCopied) onCopied();
      else announce(`Copied${filename ? ` ${filename}` : ''}`);
    } catch {
      if (onCopyFailed) onCopyFailed();
      else
        announce(
          'Copying was blocked by the browser. Select the code and copy it instead.',
          'assertive',
        );
    }
  };

  const lines = code.split('\n').length;

  return (
    <div className={['atl-code', className].filter(Boolean).join(' ')}>
      <div className="atl-code__bar">
        {filename ? <span className="atl-code__file">{filename}</span> : null}
        <span className="atl-code__lines">{lines} lines</span>
        <Button
          size="s"
          className="atl-code__copy"
          onClick={copy}
          icon={copied ? <IconCheck /> : <IconCopy />}
        >
          {copied ? 'Copied' : 'Copy'}
        </Button>
      </div>
      {html ? (
        // Highlighted ahead of time from source the author controls, never from user input.
        <div className="atl-code__body" dangerouslySetInnerHTML={{ __html: html }} />
      ) : (
        <div className="atl-code__body">
          {/* A scrollable region must be reachable by keyboard. */}
          {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}
          <pre tabIndex={0}>
            <code>
              {code.split('\n').map((line, i) => (
                // Newlines sit between line spans, as in highlighted output.
                <Fragment key={i}>
                  <span className="line">{line}</span>
                  {'\n'}
                </Fragment>
              ))}
            </code>
          </pre>
        </div>
      )}
    </div>
  );
}

@layer atlas.components {
  /* Token colours for highlighted code (Shiki's CSS-variables theme). Each reaches 5:1. */
  :root,
  [data-theme='night'] {
    --code-foreground: #dce6e4;
    --code-background: var(--sea-3);
    --code-token-keyword: #9cc3f0;
    --code-token-string: #e9bd68;
    --code-token-string-expression: #e9bd68;
    --code-token-constant: #74d3a0;
    --code-token-function: #8fd8d2;
    --code-token-parameter: #c9b6f2;
    --code-token-comment: #9db4b8;
    --code-token-punctuation: #9db4b8;
    --code-token-link: #9cc3f0;
  }

  [data-theme='day'] {
    --code-foreground: #15283a;
    --code-background: var(--sea-3);
    --code-token-keyword: #1f4f8f;
    --code-token-string: #765000;
    --code-token-string-expression: #765000;
    --code-token-constant: #1e6a46;
    --code-token-function: #0d5c5a;
    --code-token-parameter: #5b3e8f;
    --code-token-comment: #465d6d;
    --code-token-punctuation: #465d6d;
    --code-token-link: #1f4f8f;
  }

  .atl-code {
    overflow: hidden;
    border-radius: var(--radius-panel);
    background: var(--sea-3);
    color: var(--code-foreground);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 55%, transparent);
  }

  .atl-code__bar {
    display: flex;
    align-items: center;
    gap: var(--space-s);
    padding: var(--space-2xs) var(--space-2xs) var(--space-2xs) var(--space-m);
    box-shadow: inset 0 -1px 0 color-mix(in oklch, var(--isobath) 45%, transparent);
  }

  .atl-code__file {
    font-family: var(--font-code);
    font-size: var(--step--1);
  }

  .atl-code__lines {
    color: var(--ink-soft);
    font-size: var(--step--1);
  }

  .atl-code__copy {
    margin-left: auto;
  }

  .atl-code__body pre {
    max-height: 34rem;
    margin: 0;
    padding: var(--space-m) 0;
    overflow: auto;
    background: none !important;
    font-family: var(--font-code);
    font-size: 0.84rem;
    line-height: 1.6;
    tab-size: 2;
    counter-reset: line;
  }

  .atl-code__body pre:focus-visible {
    outline: var(--focus-ring);
    outline-offset: -3px;
  }

  .atl-code__body code {
    display: block;
    min-width: max-content;
  }

  .atl-code__body .line {
    display: inline-block;
    padding-right: var(--space-l);
  }

  .atl-code__body .line::before {
    content: counter(line);
    counter-increment: line;
    display: inline-block;
    width: 3.2em;
    padding-right: 1.2em;
    color: var(--ink-soft);
    text-align: right;
    user-select: none;
  }
}
